export type TwinCommunityRoleMode = "auto_heartbeat" | "manual_approval";

export interface SystemGovernanceConfig {
  /**
   * Whether Twin automatically responds to /community forum mentions on heartbeat cycles
   * or requires explicit manual human approval per message.
   */
  twinCommunityRole: TwinCommunityRoleMode;
  /**
   * Whether GitHub repository updates trigger OpenWiki re-indexing jobs automatically.
   */
  githubAutoSync: boolean;
  /**
   * Whether database migrations generated by Vibe Coder require 1-click Human Assist Handoff
   * Approval before applying DDL statements to live Postgres instances.
   */
  databaseMigrationSafety: boolean;
}

const DEFAULT_GOVERNANCE_CONFIG: SystemGovernanceConfig = {
  twinCommunityRole: "auto_heartbeat",
  githubAutoSync: true,
  databaseMigrationSafety: true,
};

let currentConfig: SystemGovernanceConfig = { ...DEFAULT_GOVERNANCE_CONFIG };

export function getSystemGovernanceConfig(): SystemGovernanceConfig {
  return { ...currentConfig };
}

export function updateSystemGovernanceConfig(
  partial: Partial<SystemGovernanceConfig>
): SystemGovernanceConfig {
  currentConfig = {
    ...currentConfig,
    ...partial,
  };
  return getSystemGovernanceConfig();
}

export function resetSystemGovernanceConfig(): SystemGovernanceConfig {
  currentConfig = { ...DEFAULT_GOVERNANCE_CONFIG };
  return getSystemGovernanceConfig();
}

export function isTwinAutoHeartbeatEnabled(): boolean {
  return currentConfig.twinCommunityRole === "auto_heartbeat";
}

export function isGithubAutoSyncEnabled(): boolean {
  return currentConfig.githubAutoSync;
}

export function isMigrationSafetyRequired(): boolean {
  return currentConfig.databaseMigrationSafety;
}
